mapper.update:
UPDATE user_search_history
SET keyword = #{keyword}, update_time = #{updateTime}
WHERE user_id = #{userId} AND normalized_keyword = #{normalizedKeyword}

mapper.select:
SELECT id, user_id, keyword, normalized_keyword, create_time, update_time
FROM user_search_history WHERE user_id = #{userId}
ORDER BY update_time DESC, id DESC LIMIT #{limit}

mapper.delete:
DELETE FROM user_search_history
WHERE user_id = #{userId} AND id NOT IN (
    SELECT id FROM (
        SELECT id FROM user_search_history WHERE user_id = #{userId}
        ORDER BY update_time DESC, id DESC LIMIT #{limit}
    ) retained
)
